function renderCurrentTimeLine() { document.querySelector('.now-line')?.remove(); if (calendarView === 'month') return; const now = new Date(); const today = localDate(now); const viewDates = datesForView(); const dayIndex = viewDates.indexOf(today); if (dayIndex < 0) return; const minutes = now.getHours() * 60 + now.getMinutes(); const grid = $('#calendar-grid'); const width = 100 / viewDates.length; const line = document.createElement('div'); line.className = 'now-line'; line.style.top = `${58 + minutes / 60 * 75}px`; line.style.left = `calc(52px + (100% - 52px) * ${dayIndex / viewDates.length})`; line.style.width = `calc((100% - 52px) * ${1 / viewDates.length})`; grid.appendChild(line); const card = $('.calendar-card'); if (card && !card.dataset.initialScrolled) { card.scrollTop = Math.max(0, minutes / 60 * 75 - 140); card.dataset.initialScrolled = 'true'; } }
